'use strict'

import soundManager from '../service/sound-manager'
import resource from '../resource'
import { overlaps } from '../utils/box'
import { directionOf, drawImage } from './enemies/common'
import { revealAt } from './secret'
import { TILE_WIDTH, TILE_HEIGHT, SOUND_BOMB_BLOW, SECRET_BOMB, NES_PIXEL } from '../constant'

// Measured in the ROM, in frames (game steps): the fuse burns 48 frames, then the smoke stays 24 frames
// big and 12 frames smaller. Link has one bomb at a time
export const FUSE_STEPS = 48
const BIG_SMOKE_STEPS = 24
const SMALL_SMOKE_STEPS = 12
export const BLAST_STEPS = BIG_SMOKE_STEPS + SMALL_SMOKE_STEPS
// As strong as the magical sword
export const BOMB_DAMAGE = 4
// The 7 clouds of smoke around the bomb (NES pixels, doubled here), drawn 4 at a time, one set every
// other frame, as in the original
const CLOUDS = [
  [[0, 0], [-13, 0], [7, -13], [-7, 14]],
  [[0, 0], [14, 0], [-7, -13], [7, 14]]
]
// What the blast reaches: two tiles wide, around the bomb (the clouds, roughly)
const BLAST_REACH = TILE_WIDTH / 2

export class Bomb {
  constructor (x, y) {
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.steps = 0
    this.done = false
    this.hitEnemies = new Set() // Each enemy is hit once by a blast
  }

  get isExploding () {
    return this.steps >= FUSE_STEPS
  }

  getBlastBox () {
    return { x: this.x - BLAST_REACH, y: this.y - BLAST_REACH, width: this.width + 2 * BLAST_REACH, height: this.height + 2 * BLAST_REACH }
  }

  blast (map, link) {
    const box = this.getBlastBox()
    for (const enemy of map.activeEnemies) {
      if (this.hitEnemies.has(enemy) || !enemy.isVulnerable || !overlaps(box, enemy.getBox())) {
        continue
      }
      this.hitEnemies.add(enemy)
      // Pushed away from the bomb
      const direction = directionOf(enemy.x - this.x, enemy.y - this.y)
      enemy.hit(link, { damage: BOMB_DAMAGE, direction, byBomb: true })
    }
  }

  process (map, link) {
    this.steps++
    if (this.steps === FUSE_STEPS) {
      soundManager.play(resource.getSound(SOUND_BOMB_BLOW))
      // A wall hiding a cave less than a tile away opens
      revealAt(map, this, SECRET_BOMB)
    }
    if (this.isExploding) {
      this.blast(map, link)
    }
    if (this.steps >= FUSE_STEPS + BLAST_STEPS) {
      this.done = true
    }
  }

  draw (context) {
    if (!this.isExploding) {
      resource.getSprite('item_bomb')?.draw(context, this.x, this.y, this.width, this.height)
      return
    }
    const frame = this.steps < FUSE_STEPS + BIG_SMOKE_STEPS ? 0 : 1
    const sprite = resource.getSprite('misc_bomb_blow')
    for (const [dx, dy] of CLOUDS[this.steps % 2]) {
      drawImage(context, sprite, frame, this.x + NES_PIXEL * dx, this.y + NES_PIXEL * dy, this.width, this.height)
    }
  }
}
