'use strict'

import io from './utils/io'
import soundManager from './service/sound-manager'
import { PATH_DATA_SPRITES, PATH_SPRITES_IMAGE, PATH_DATA_SOUNDS, PATH_AUDIO_SOUNDS, SPRITE_SHEET_CELL, PATH_PACKS, PATH_PACKS_FOLDER, PACK_LAYOUT_ORIGINAL } from './constant'
import { Sprite, SpriteImage } from './model/resource/sprite'
import { expandSprites, paintFrame } from './model/resource/sprite-palette'
import { placeFrames, matchNames, applyImages } from './model/resource/graphics-pack'
import { Sound } from './model/resource/sound'

const sprites = {}
const sounds = {}
// The images of the graphics of the ROM, and their data (for the packs drawn on the same sheet)
const originalImages = {}
let spriteData = []
// The widest an atlas gets, in pixels
const MAX_ATLAS_WIDTH = 4096

// The sprites of the data (see sprite-palette.js) on an indexed sheet drawn scale times finer than the NES: every
// frame painted with its colours into one atlas, side by side. name → { type, images }
function paintSprites (dataSprites, sheetImage, scale, smooth) {
  const sheetCanvas = document.createElement('canvas')
  sheetCanvas.width = sheetImage.width
  sheetCanvas.height = sheetImage.height
  const sheetContext = sheetCanvas.getContext('2d')
  sheetContext.drawImage(sheetImage, 0, 0)
  const sheet = sheetContext.getImageData(0, 0, sheetCanvas.width, sheetCanvas.height).data

  const expanded = expandSprites(dataSprites)
  const frames = expanded.flatMap(sprite => sprite.frames.map(frame => ({ sprite, frame, width: sprite.width * scale, height: sprite.height * scale })))
  const { places, width, height } = placeFrames(frames, Math.min(MAX_ATLAS_WIDTH, 1024 * scale))
  const atlas = document.createElement('canvas')
  atlas.width = width
  atlas.height = height
  const atlasContext = atlas.getContext('2d')
  const painted = {}
  frames.forEach(({ sprite, frame, width, height }, i) => {
    const pixels = paintFrame(sheet, sheetCanvas.width, frame, width, height, SPRITE_SHEET_CELL * scale)
    atlasContext.putImageData(new ImageData(pixels, width, height), places[i].x, places[i].y)
    painted[sprite.name] ??= { type: sprite.type, images: [] }
    painted[sprite.name].images.push(new SpriteImage(sprite.name, atlas, places[i], sprite.width, sprite.height, scale, smooth))
  })
  return painted
}

export default {
  loadAll: async function () {
    const resources = await io.fetchRemoteFiles(PATH_DATA_SPRITES, PATH_SPRITES_IMAGE, PATH_DATA_SOUNDS, PATH_AUDIO_SOUNDS)
    const dataSprites = resources[0]
    const spritesImage = resources[1]
    const dataSounds = resources[2]
    const audioSounds = resources[3]
    this.loadSprites(dataSprites, spritesImage)
    await this.loadSounds(dataSounds, audioSounds)
  },
  loadSprites: async function (dataSprites, spritesImage) {
    if (!dataSprites || !spritesImage) {
      const resources = await io.fetchRemoteFiles(PATH_DATA_SPRITES, PATH_SPRITES_IMAGE)
      dataSprites = resources[0]
      spritesImage = resources[1]
    }
    spriteData = dataSprites
    for (const [name, { type, images }] of Object.entries(paintSprites(dataSprites, spritesImage, 1, false))) {
      originalImages[name] = images
      sprites[name] = new Sprite(name, type, [...images])
    }
  },
  // The graphics packs to choose from ([{ id, name }]); none when the list is missing
  loadPackList: async function () {
    try {
      return await io.fetchRemoteFile(PATH_PACKS)
    } catch (e) {
      return []
    }
  },
  // The images of a pack (name of a sprite → images), see graphics-pack.js and docs/data-format.md
  loadPack: async function (id) {
    const folder = `${PATH_PACKS_FOLDER}/${id}`
    const pack = await io.fetchRemoteFile(`${folder}/pack.json`)
    const image = await io.fetchRemoteFile(`${folder}/${pack.image}`)
    if (pack.layout === PACK_LAYOUT_ORIGINAL) {
      // The sheet of the ROM drawn again, scale times finer: same places, same colour indices
      const painted = paintSprites(spriteData, image, pack.scale, !!pack.smooth)
      return Object.fromEntries(Object.entries(painted).map(([name, { images }]) => [name, images]))
    }
    const names = Object.keys(sprites)
    const byName = {}
    for (const entry of pack.sprites) {
      const width = entry.width ?? entry.size ?? SPRITE_SHEET_CELL
      const height = entry.height ?? entry.size ?? SPRITE_SHEET_CELL
      const images = entry.frames.map(frame => new SpriteImage(entry.name, image, { x: frame.x, y: frame.y }, width, height, pack.scale, !!pack.smooth))
      for (const name of matchNames(entry.name, names)) {
        byName[name] = images
      }
    }
    return byName
  },
  // Switches the graphics: those of a pack (from loadPack), or the original ones (undefined)
  usePack: function (byName) {
    applyImages(sprites, originalImages, byName)
  },
  cloneSprite: (name) => {
    return sprites[name] ? sprites[name].clone() : undefined
  },
  getItemSprite: (name) => {
    return sprites[`item_${name}`]
  },
  getSprite: (name) => {
    return sprites[name]
  },
  loadSounds: async function (dataSounds, audioSounds) {
    const context = soundManager.getContext()
    const gainNode = soundManager.getGainNode()
    if (!context || !gainNode) {
      throw new Error('Audio context must be initialized before loading sounds')
    }
    if (!dataSounds || !audioSounds) {
      const resources = await io.fetchRemoteFiles(PATH_DATA_SOUNDS, PATH_AUDIO_SOUNDS)
      dataSounds = resources[0]
      audioSounds = resources[1]
    }
    for (let i = 0; i < dataSounds.length; i++) {
      const dataSound = dataSounds[i]
      const bytes = dataSound.bytes
      const offset = dataSound.offset
      const arrayBuffer = audioSounds.slice(offset, offset + bytes)
      const audioBuffer = await context.decodeAudioData(arrayBuffer)
      const name = dataSound.name
      const duration = dataSound.duration || undefined
      const loop = dataSound.loop || false
      const loopEnd = dataSound.loop_end || 0
      const loopStart = dataSound.loop_start || 0
      sounds[name] = new Sound(name, audioBuffer, context, gainNode, duration, loop, loopStart, loopEnd)
    }
  },
  cloneSound: (name) => {
    return sounds[name] ? sounds[name].clone() : undefined
  },
  getSound: (name) => {
    return sounds[name]
  },
  stopAllSounds: () => {
    for (const sound of Object.values(sounds)) {
      soundManager.stop(sound)
    }
  }
}
